    "deepDive": [
      {
        "title": "형사망의 확대(net-widening)가 실제로 일어나는 방식",
        "body": "이 비판은 단순한 우려가 아니라 다이버전 프로그램 평가 연구에서 반복 관찰된 결과다. 기제는 세 가지로 정리된다. 첫째, 대상 확대(wider net) — 종전에 훈방되었을 사람이 프로그램 대상자로 편입된다. 둘째, 통제 강화(stronger net) — 종전보다 강한 개입을 받는 사람이 생긴다. 예컨대 단순 기소유예로 끝났을 사건이 조건부 기소유예가 되어 프로그램 이수 의무가 붙는다. 셋째, 새로운 망(different net) — 형사사법이 아닌 복지ㆍ의료기관이 새 통제 주체로 등장한다. 다이버전이 자원을 절약하려던 목적과 반대로, 관리 대상과 비용이 함께 늘어나는 역설이 여기서 나온다."
      },
      {
        "title": "비범죄화의 두 갈래 — 법률상과 사실상",
        "body": "비범죄화는 입법으로 처벌 규정을 삭제하는 법률상 비범죄화(de jure)와, 규정은 남아 있으나 수사ㆍ기소가 사실상 이루어지지 않아 처벌되지 않는 사실상 비범죄화(de facto)로 나뉜다. 사실상 비범죄화는 법이 그대로 있으므로 언제든 다시 집행될 수 있고, 집행 여부가 기관 재량에 달려 자의적 적용의 위험을 안는다는 점이 지적된다. 논의 대상으로 흔히 거론되는 영역은 피해자 없는 범죄(victimless crime) — 자기 자신만을 해하거나 성인의 합의에 기초한 행위군이다. 「피해자 없는 범죄」라는 개념 자체가 형법이 보호할 법익이 실제로 존재하는지를 되묻는 도구로 쓰였다는 점에서, 비범죄화 논의는 형법의 보충성ㆍ최후수단성 원칙과 맞닿아 있다."
      }
    ],
