        "title": "상호작용이론 — 낙인의 일방향을 상호작용으로 고친 수정",
        "body": "손베리(Terence Thornberry)의 상호작용이론(1987)은 기존 이론들이 대체로 「원인 → 비행」의 일방향 모형을 쓴 데 대해, 실제 관계는 양방향의 되먹임이라고 주장한다. 예컨대 부모와의 애착 약화가 비행을 낳지만, 비행이 다시 부모와의 관계를 악화시켜 애착을 더 떨어뜨린다. 비행 친구와의 접촉이 비행을 늘리고, 비행이 다시 비행 친구와의 접촉을 늘린다. 나아가 이 이론은 생애 단계마다 지배적 변수가 달라진다고 본다 — 초기 청소년기에는 가족의 영향이 가장 크고, 중기에는 친구와 학교가, 후기에는 직업ㆍ배우자ㆍ자녀 등 성인기 역할이 중요해진다. 낙인이론이 「사회적 반응이 일탈을 만든다」는 한 방향을 강조했다면, 상호작용이론은 그 반응과 행위가 서로를 강화하는 나선을 그린다고 본 것이다."
