        "title": "암수범죄 — 낙인이론이 공식통계를 못 믿게 만든 자리",
        "body": "암수범죄(dark figure)는 실제로 발생했으나 수사기관에 인지되지 않았거나 인지되었어도 공식통계에 잡히지 않은 범죄를 말한다. 낙인이론이 「누가 일탈자가 되는가는 사회적 반응이 정한다」고 주장하면서, 공식 범죄통계가 실제 범죄 분포가 아니라 형사사법기관의 활동 분포를 보여 줄 뿐이라는 문제의식이 부각되었다. 암수의 원인은 크게 셋이다 — 피해자가 신고하지 않는 경우(보복 우려, 수치심, 피해 인식 부재, 성범죄ㆍ가정폭력에서 특히 크다), 수사기관이 인지하고도 입건하지 않는 경우(훈방ㆍ재량적 처리), 피해자 없는 범죄처럼 신고 주체가 없는 경우. 이를 보완하려는 조사 방법이 두 가지 개발되었다. 피해자조사(victimization survey)는 표본에게 피해 경험을 직접 묻고, 자기보고식조사(self-report survey)는 응답자에게 자신이 저지른 행위를 묻는다. 전자는 살인처럼 피해자가 진술할 수 없는 범죄와 피해자 없는 범죄에 약하고, 후자는 경미한 비행에는 유효하나 중대범죄에서는 응답의 진실성이 떨어진다는 한계를 각각 안는다."
