        "body": "펠슨은 표적이 「적합한」지를 네 요소로 설명한다. 가치(Value) — 범죄자에게 얼마나 값어치가 있는가. 이동가능성(Inertia) — 들고 갈 수 있을 만큼 가볍고 작은가. 가시성(Visibility) — 범죄자의 눈에 띄는가. 접근성(Access) — 다가가고 빠져나오기 쉬운가. 노트북과 스마트폰이 절도의 표적이 되기 쉬운 이유가 이 네 조건을 모두 만족하기 때문이다. 한편 보호자도 경찰만을 뜻하지 않는다. 후속 논의는 이를 셋으로 나눈다 — 표적을 지키는 보호자(guardian, 이웃ㆍCCTV), 잠재적 범죄자를 통제하는 관리자(handler, 부모ㆍ교사), 장소를 관리하는 장소관리자(place manager, 건물 관리인ㆍ점포 주인). 범죄 예방의 개입 지점이 세 갈래로 늘어나는 셈이다."
