        "body": "윌슨과 켈링(Wilson & Kelling)의 깨진 유리창 이론(1982)은 방치된 무질서 신호(깨진 창문, 낙서, 쓰레기)가 「여기는 아무도 신경 쓰지 않는다」는 메시지를 보내고, 그 결과 주민의 비공식적 통제가 위축되면서 중한 범죄로 이어진다고 주장했다. 이 논리가 1990년대 뉴욕의 무관용 경찰활동(zero tolerance)으로 이어지면서 큰 논쟁이 벌어졌다. 지지 측은 같은 시기 뉴욕의 범죄 급감을 근거로 들었으나, 반대 측은 같은 기간 전국적으로 범죄가 감소했고 인구구조 변화ㆍ경제 호전ㆍ마약시장 변화 등 다른 요인이 컸다고 반박했다. 또한 경미한 무질서에 대한 강경 단속이 특정 계층과 인종에 집중되어 차별적 법집행을 낳는다는 비판이 뒤따랐다. 이 논쟁은 「환경을 고치는 접근」이 정책으로 옮겨질 때 어디까지가 예방이고 어디부터가 통제의 확장인지를 묻는 사례로 자주 인용된다."
