    "deepDive": [
      {
        "title": "누진처우의 계보 — 점수제에서 우리 경비등급까지",
        "body": "누진처우는 형기를 고정된 기간이 아니라 「성적에 따라 단축될 수 있는 것」으로 바꾼 발상이다. 마코노키의 점수제가 그 출발점으로, 형기를 점수로 환산하고 노동과 선행으로 점수를 상환하면 석방에 다가가게 했다. 크로프턴은 여기에 사회 복귀의 완충지대를 더해 독거 → 혼거 → 중간교도소 → 가석방의 4단계로 정리했고, 중간교도소는 오늘날 중간처우시설(halfway house)의 원형이 되었다. 엘마이라는 이를 부정기형과 결합해 「성적이 곧 석방 시기」라는 구조를 완성했다. 우리 형집행법의 구조도 이 계보 위에 있다 — 분류심사로 처우 수준을 정하고(제59조 이하), 경비등급을 개방ㆍ완화경비ㆍ일반경비ㆍ중경비 넷으로 나누며(제57조 제2항), 성적에 따라 개방처우ㆍ외부통근ㆍ귀휴로 단계적으로 사회에 가까워지게 한다. 다만 부정기형은 소년법 제60조에만 남아 있고 성인에게는 채택되지 않았다."
      },
      {
        "title": "20세기 처우모델의 교체가 남긴 것",
        "body": "의료모델(medical model)은 범죄를 질병으로, 범죄자를 치료 대상으로 보아 진단ㆍ처방ㆍ치료의 틀을 행형에 옮겼다. 부정기형과 전문가의 광범한 재량이 그 결과였다. 개선모델(adjustment model)은 여기에 범죄자의 자기 책임과 참여를 더했다. 그러나 1974년 마틴슨의 평가 연구가 처우 프로그램의 효과를 부정적으로 요약하면서 흐름이 뒤집힌다. 정의모델(justice model)은 응분의 처벌과 정기형, 적법절차와 수용자의 권리 보장을 내세웠고, 재량의 축소가 그 핵심이었다. 재통합모델(reintegration model)은 다른 각도에서 답했다 — 문제는 처우의 효과가 아니라 그것이 시설 안에서만 이루어진다는 데 있으므로, 지역사회와의 연결을 유지한 채 처우해야 한다는 것이다. 중간처우, 사회내처우, 갱생보호가 이 모델의 자리다. 오늘날 교정은 어느 한 모델의 승리가 아니라 이 넷의 요소를 함께 안고 있다 — 분류와 처우(의료ㆍ개선), 권리구제와 적법절차(정의), 사회복귀 지원(재통합)이 같은 법률 안에 나란히 들어 있는 이유다."
      }
    ],
